    #[test]
    fn test_mixed() {
        let ops = vec![
            NumpyOperand::Scalar(NumpyDType::Int8),
            NumpyOperand::Array(NumpyDType::Float32),
            NumpyOperand::Scalar(NumpyDType::Float64),
            NumpyOperand::Array(NumpyDType::Int64),
        ];
        assert_eq!(result_type(ops), NumpyDType::Float64);
    }

    #[test]
